{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0007",
          "reason": "Conventional conflict de-escalation and emergency-law reversal, not direct nuclear or other existential-risk conduct."
        },
        {
          "evidence_id": "E0008",
          "reason": "Humanitarian truce evidence for the Tigray war; relevant to conflict management, but not direct 1B risk-bearing choice."
        },
        {
          "evidence_id": "E0009",
          "reason": "Peace-talk conclusion and settlement evidence; useful background, not proof of nuclear or catastrophic-risk stewardship."
        },
        {
          "evidence_id": "E0010",
          "reason": "Post-agreement humanitarian access and service restoration are downstream conflict effects, not 1B-specific conduct."
        },
        {
          "evidence_id": "E0011",
          "reason": "Countrywide humanitarian baseline only; it frames inherited conditions but does not show ruler-attributed existential-risk action."
        },
        {
          "evidence_id": "E0012",
          "reason": "Conflict-atrocity allegation evidence belongs primarily to 2B/3B; it is not direct nuclear or existential-risk evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 evidence of Abiy Ahmed making a nuclear, CBRN, cyber, AI, or other catastrophic-risk decision within his actual authority.",
          "lenses": ["1B.1", "1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "Archived PMO/cabinet statements in Ethiopian languages, defense and security appointment records, IAEA/CTBTO registry material, and any 2022 policy text on dual-use or emergency-risk governance.",
          "why_it_matters": "Without a target-period risk-bearing choice, the chapter cannot fairly distinguish conduct from inherited context."
        },
        {
          "gap": "No command-and-control or custody/safeguards evidence specific to 2022 beyond treaty baseline and formal office structure.",
          "lenses": ["1B.3", "1B.7", "1B.8"],
          "best_source_or_query_direction": "Defense ministry records, military appointments, declassified or contemporaneous official statements, and serious scholarship on Ethiopian security governance in 2022.",
          "why_it_matters": "The rubric needs ruler-attributed safety governance, not just formal authority."
        },
        {
          "gap": "The package relies on conventional-war de-escalation as a proxy for existential-risk posture, which is only indirect support.",
          "lenses": ["1B.1", "1B.8", "1B.10"],
          "best_source_or_query_direction": "UN/AU follow-up on whether the 2022 peace process materially reduced catastrophic-risk exposure, plus any direct state statements on existential-risk policy.",
          "why_it_matters": "Indirect peace evidence can inform exposure, but it should not be mistaken for direct 1B performance."
        }
      ],
      "reason": "The file establishes authority, treaty context, and 2022 de-escalation moves, but it does not contain direct target-period nuclear or other catastrophic-risk choices. The chapter is therefore a real exposure/background gap, not a fair basis for a substantive 1B judgment."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Exact internal command responsibility for allied atrocities and Eritrean force activity remains only partly exposed.",
          "lenses": ["2B.4", "2B.5", "2B.9", "2B.10"],
          "best_source_or_query_direction": "UN/OHCHR follow-up, EHRC releases, AU implementation notes, and independent investigative reporting on the 2022 conflict command chain.",
          "why_it_matters": "The package can fairly show the conflict record, but finer attribution would sharpen the ruler-specific responsibility judgment."
        },
        {
          "gap": "Implementation of the November peace agreement is documented but not fully audited nationwide.",
          "lenses": ["2B.7", "2B.10"],
          "best_source_or_query_direction": "UN OCHA, UNHCR/WFP field updates, signed implementation notes, and reputable local reporting on disarmament, access, and service restoration.",
          "why_it_matters": "The package shows a peace pivot, but the durability and completeness of that pivot remain only partially verified."
        }
      ],
      "reason": "The chapter is balanced enough to present both restraint and grave wartime harm, with contrary evidence and attribution caveats. It is usable as a mixed 2022 peace-and-war record even though the exact command chain is not fully resolved."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct ruler-level command attribution for regional crackdowns and Western Tigray abuses is still incomplete.",
          "lenses": ["3B.1", "3B.2", "3B.5", "3B.9"],
          "best_source_or_query_direction": "EHRC, court or inquiry records, UN human-rights material, and independent investigations on federal-regional security coordination.",
          "why_it_matters": "The package shows severe domestic harm, but the exact center-of-command line would sharpen fairness and responsibility."
        },
        {
          "gap": "National trends in detention, protest treatment, and media pressure are strong, but the boundary between federal direction and regional implementation is not always clean.",
          "lenses": ["3B.4", "3B.8", "3B.10"],
          "best_source_or_query_direction": "Independent monitoring by CPJ, HRW, Amnesty, Freedom House, and Ethiopian legal or oversight records.",
          "why_it_matters": "The chapter needs both pattern evidence and attribution discipline, especially in a fragmented wartime environment."
        }
      ],
      "reason": "The package fairly presents a restrictive and harmful domestic-safety record alongside some de-escalatory steps. It preserves contrary evidence and uncertainty, and the remaining weakness is attribution depth rather than basic fairness."
    },
    {
      "chapter_id": "4B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0042",
          "reason": "Formal partnership agreement shows institutional packaging, not independent proof of a genuinely open or contestable political process."
        },
        {
          "evidence_id": "E0037",
          "reason": "Annual rights summary is useful context, but it mixes multiple actors and should not be treated as a clean direct measure of contestability."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 evidence on electoral contestability, succession, and term-limit behavior is inherently thin because there was no national election or transfer event.",
          "lenses": ["4B.1", "4B.2", "4B.8"],
          "best_source_or_query_direction": "Election-board records, constitutional/legal records, observer reports, court records, and contemporaneous political-process reporting.",
          "why_it_matters": "The chapter can still be reviewed, but the absence of a 2022 test event means the package cannot richly answer some core lenses."
        },
        {
          "gap": "Civic-space restrictions are well documented, but the legal basis and command path are only partly exposed.",
          "lenses": ["4B.3", "4B.6", "4B.9"],
          "best_source_or_query_direction": "Legal texts, internal directives if available, court filings, and stronger local investigative reporting on the press blockade, internet shutdown, and accreditation revocations.",
          "why_it_matters": "The package can show restriction, but better attribution would separate policy choice from wartime security justification."
        }
      ],
      "reason": "The file clearly shows a restrictive political environment and some limited liberalizing steps, but it remains thin on direct 2022 contestability and transfer evidence. That is enough for a usable dossier, but not yet a fully saturated one."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent budget-execution and outturn evidence is limited, so the record is stronger on intent than on verified delivery.",
          "lenses": ["5B.3", "5B.6", "5B.9", "5B.10"],
          "best_source_or_query_direction": "Audited budget outturns, IMF Article IV material, central-bank and finance-ministry execution reports, and sector-specific spending reviews.",
          "why_it_matters": "The package can present a mixed economic record, but outcome confidence depends on whether priorities were actually implemented."
        },
        {
          "gap": "Appointment quality and anti-capture evidence beyond the finance portfolio is thin.",
          "lenses": ["5B.2", "5B.5", "5B.7"],
          "best_source_or_query_direction": "Cabinet appointment records, procurement audits, SOE oversight material, and investigative reporting on economic patronage or technocratic delegation.",
          "why_it_matters": "The chapter needs more than macro policy intent to distinguish competent stewardship from favorable framing."
        }
      ],
      "reason": "The package fairly presents a mixed economic year: reform intent, some pro-poor and reconstruction spending, severe inflation and debt stress, and meaningful constraints. The main weakness is execution verification, not missing narrative balance."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Delivery and outcome evidence still leans heavily on program announcements and donor reporting rather than full independent outturn audits.",
          "lenses": ["6B.2", "6B.6", "6B.10"],
          "best_source_or_query_direction": "Household surveys, sector administrative data, audited program results, and independent evaluations from WHO, UNICEF, World Bank, and Ethiopian ministries.",
          "why_it_matters": "The chapter can show welfare priorities and crisis response, but stronger outcome verification would tighten ruler attribution."
        },
        {
          "gap": "Region-by-region and vulnerable-group distribution data is not yet deep enough to fully test equity claims.",
          "lenses": ["6B.3", "6B.8", "6B.9"],
          "best_source_or_query_direction": "Subnational health, education, nutrition, and WASH data; conflict-area program evaluations; and UNICEF/WHO field reporting.",
          "why_it_matters": "The chapter is about human development and dignity, so distributional evidence matters as much as headline totals."
        }
      ],
      "reason": "The chapter is fair and usable: it separates crisis context from ruler-linked welfare choices and shows both gains and severe shortfalls. The remaining issue is depth of delivery verification, not basic evidentiary balance."
    },
    {
      "chapter_id": "7B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0071",
          "reason": "Country-level transparency and press-freedom context does not by itself establish Abiy Ahmed's personal dishonesty or self-dealing."
        },
        {
          "evidence_id": "E0072",
          "reason": "Broader repression reporting is relevant to the political environment, but it is not direct personal-nexus evidence of integrity or corruption."
        },
        {
          "evidence_id": "E0069",
          "reason": "A cabinet roster proves officeholding only; it cannot show merit, favoritism, or personal integrity without more direct linkage."
        },
        {
          "evidence_id": "E0081",
          "reason": "The asset-disclosure legal framework is institutional context, not proof of Abiy's own filing, compliance, or concealment."
        }
      ],
      "material_gaps": [
        {
          "gap": "No traceable 2022 evidence of Abiy's own asset declarations, beneficial interests, or enforcement outcomes.",
          "lenses": ["7B.3", "7B.4", "7B.6"],
          "best_source_or_query_direction": "FEACC filings, audit and procurement records, court findings, and investigative reporting on the prime minister's immediate circle.",
          "why_it_matters": "The chapter requires personal-nexus evidence, not just state-level corruption context."
        },
        {
          "gap": "The evidence on truthfulness and correction is mostly about public statements and repression, not independent proof of deliberate personal deception.",
          "lenses": ["7B.1", "7B.2", "7B.7", "7B.10"],
          "best_source_or_query_direction": "Direct speeches, official transcripts, adverse fact-checks tied to specific statements, and independent investigative reporting.",
          "why_it_matters": "State coercion can coexist with personal candor; the chapter cannot conflate them."
        },
        {
          "gap": "Appointment and patronage evidence is partial, with one technocratic finance minister but no systematic 2022 map of the wider governing network.",
          "lenses": ["7B.5", "7B.9"],
          "best_source_or_query_direction": "Full cabinet and senior-staff bios, nepotism or patronage investigations, and procurement or appointment audits.",
          "why_it_matters": "Integrity scoring needs pattern evidence across the governing circle, not a single favorable biography."
        }
      ],
      "reason": "The package shows a real coercive and media-control record, plus some anti-corruption and peace signaling, but it does not establish the required personal-nexus evidence for self-enrichment, hidden conflicts, or compliance with asset-disclosure rules. That makes this chapter gap-heavy rather than fully reviewable."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent execution and outcome audits are still thin, so the package leans on official program design and partner corroboration.",
          "lenses": ["8B.6", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Audited budgets, implementation scorecards, UN/World Bank follow-up, and sector outturn reports on Tigray restoration, anti-corruption enforcement, and service delivery.",
          "why_it_matters": "The chapter can show program direction and some follow-through, but not yet the full quality of execution."
        },
        {
          "gap": "Personnel and coordination evidence is strongest in the finance and planning portfolios, but thin elsewhere.",
          "lenses": ["8B.4", "8B.5"],
          "best_source_or_query_direction": "Cabinet appointment records, internal evaluation material, ministry implementation reports, and independent administrative analyses.",
          "why_it_matters": "Effectiveness depends on the whole implementation chain, not just a few visible ministries."
        }
      ],
      "reason": "The package fairly captures Abiy's 2022 program, the implementation steps taken, and the constraints facing them. The main limitation is that much of the evidence is still official or partner-reported, so the file is usable but not fully independently audited."
    }
  ]
}
